pub const Stack = struct {
    id: Id,
    uses: u16,
    identified: bool = true,
    pub fn name(self: Stack) []const u8 {
        return if (self.identified) self.id.name() else switch (self.id) {
            .graffiti, .flower_painting, .lover_s_garden, .landscape_painting, .beauties_of_nature, .junk => "? painting",
            .hex_doll, .japanese_dish, .chinese_dish, .peeing_boy, .bonsai, .knight_statue, .goddess_statue => "? ornament",
            else => "? pot",
        };
    }
};
pub const Inventory = struct {
    slots: [9]?Stack = .{ null, null, null, null, null, null, null, null, null },

    pub fn receive(self: *Inventory, id: Id) !bool {
        try self.validate();
        const slot = self.count();
        if (slot == self.slots.len) return false;
        self.slots[slot] = .{ .id = id, .uses = id.maxUses(), .identified = !id.decoration() };
        return true;
    }

    pub fn count(self: Inventory) usize {
        for (self.slots, 0..) |slot, i| if (slot == null) return i;
        return self.slots.len;
    }

    pub fn validate(self: Inventory) !void {
        var empty = false;
        for (self.slots) |slot| {
            if (slot) |item| {
                if (!item.identified and !item.id.decoration()) return error.InvalidInventory;
                if (empty or (item.id.maxUses() > 0 and item.uses == 0) or item.uses > item.id.maxUses()) return error.InvalidInventory;
            } else empty = true;
        }
    }

    pub fn remove(self: *Inventory, index: usize) void {
        std.mem.copyForwards(?Stack, self.slots[index..8], self.slots[index + 1 .. 9]);
        self.slots[8] = null;
    }
    pub fn spendUse(self: *Inventory, index: usize, id: Id) !void {
        if (index >= self.count() or self.slots[index].?.id != id or self.slots[index].?.uses == 0) return error.InvalidItem;
        self.slots[index].?.uses -= 1;
        if (self.slots[index].?.uses == 0) self.remove(index);
    }
};
