pub const Consumable = struct {
    id: Id,
    name: []const u8,
    price: u32,
    uses: u16,
    heal_hp: u16 = 0,
    cure: ?enum { poison, balloon } = null,
    battle: ?BattleUse = null,
    field_usable: bool = true,
    pub fn partyWide(self: Consumable) bool {
        return if (self.battle) |effect| effect.targeting == .party else false;
    }
    pub fn applyTo(self: Consumable, member: anytype, protected: bool) u16 {
        const before = member.hp;
        if (!protected) member.hp = @intCast(@min(@as(u32, member.hp) + self.heal_hp, member.max_hp));
        if (self.cure) |cure| switch (cure) {
            .poison => if (member.status == .poisoned) {
                member.status = .healthy;
            },
            .balloon => member.balloons -|= 1,
        };
        return member.hp - before;
    }
};
pub const AutomaticRevival = struct {
    id: Id,
    name: []const u8,
    price: u32,
    hp_divisor: u16,
    clone_birth: u16,
    clone_motion_start: u16,
    clone_motion_stop: u16,
    clone_release: u16,
    white_start: u16,
    white_end: u16,
    pending_delay: u16,
    impact_delay: u16,
    recovery_start: u16,
    release_delay: u16,
    particle_tint: [3]u8,
    particle_plane_z: i16,
    particles: []const [4][2]f32,
    pub fn validate(self: AutomaticRevival) !void {
        if (self.id != .sacrificial_buddha or !std.mem.eql(u8, self.name, self.id.name()) or self.price != 5000 or self.hp_divisor != 2 or
            self.clone_birth != 16 or self.clone_motion_start != 18 or self.clone_motion_stop != 77 or self.clone_release != 110 or
            self.white_start != 78 or self.white_end != 109 or self.pending_delay != 112 or self.impact_delay != 113 or self.recovery_start != 113 or
            self.release_delay != 123 or self.particle_plane_z != 0 or !std.mem.eql(u8, &self.particle_tint, &.{ 128, 0, 0 }) or self.particles.len != 59) return error.InvalidItems;
        for (self.particles) |row| for (row) |position| for (position) |v| if (!std.math.isFinite(v) or @abs(v) > 50) return error.InvalidItems;
    }
};
pub const Rules = struct {
    appraisals: []const Appraisal = &.{},
    schema: []const u8,
    room: []const u8,
    npc: []const u8,
    greeting: []const u8,
    medicine: Medicine,
    consumables: []const Consumable = &.{},
    battle_reusables: []const Consumable = &.{},
    automatic_revival: ?AutomaticRevival = null,
    goods: []const Good = &.{},
    equipment_goods: []const Good = &.{},
    stock: []const Id = &.{.medicine},

    pub fn consumable(self: Rules, id: Id) ?Consumable {
        for (self.consumables) |item| if (item.id == id) return item;
        for (self.battle_reusables) |item| if (item.id == id) return item;
        if (id == .medicine) return .{ .id = id, .name = self.medicine.name, .price = self.medicine.price, .uses = self.medicine.uses, .heal_hp = self.medicine.heal_hp };
        return null;
    }

    pub fn stocked(self: Rules, id: Id) bool {
        for (self.stock) |item| if (item == id) return true;
        return false;
    }
    pub fn good(self: Rules, id: Id) ?Good {
        if (self.automatic_revival) |item| if (item.id == id) return .{ .id = id, .name = item.name, .price = item.price, .uses = 0 };
        for (self.goods) |item| if (item.id == id) return item;
        if (self.consumable(id)) |item| return .{ .id = item.id, .name = item.name, .price = item.price, .uses = item.uses };
        return null;
    }

    pub fn offerGood(self: Rules, id: Id) ?Good {
        if (self.good(id)) |item| return item;
        for (self.equipment_goods) |item| if (item.id == id) return item;
        return null;
    }

    pub fn validate(self: Rules) !void {
        const automatic = std.mem.eql(u8, self.schema, "suikoden-items/7");
        const reusables = automatic or std.mem.eql(u8, self.schema, "suikoden-items/6");
        if (automatic != (self.automatic_revival != null)) return error.InvalidItems;
        if (self.automatic_revival) |item| try item.validate();
        const battle_items = reusables or std.mem.eql(u8, self.schema, "suikoden-items/5");
        if (battle_items or std.mem.eql(u8, self.schema, "suikoden-items/4")) {
            for ([_]Id{ .failure_urn, .octopus_urn, .celadon_urn }) |required| {
                var found = false;
                for (self.appraisals) |item| found = found or item.id == required;
                if (!found) return error.InvalidItems;
            }
        }
        if (self.appraisals.len > 22) return error.InvalidItems;
        for (self.appraisals, 0..) |item, i| {
            if (!item.id.decoration() or item.fee == 0 or item.fee > 999999 or item.price == 0 or !std.mem.eql(u8, item.name, item.id.name())) return error.InvalidItems;
            for (self.appraisals[0..i]) |other| if (other.id == item.id) return error.InvalidItems;
        }
        const legacy = std.mem.eql(u8, self.schema, "suikoden-items/1");
        if (!legacy and !std.mem.eql(u8, self.schema, "suikoden-items/2") and !std.mem.eql(u8, self.schema, "suikoden-items/3") and !std.mem.eql(u8, self.schema, "suikoden-items/4") and !battle_items) return error.UnsupportedItemSchema;
        if (self.goods.len > 64 or self.equipment_goods.len > 64) return error.InvalidItems;
        for (self.goods, 0..) |item, i| {
            if (item.uses != 0 or item.id.maxUses() != 0 or !std.mem.eql(u8, item.name, item.id.name())) return error.InvalidItems;
            for (self.goods[0..i]) |other| if (other.id == item.id) return error.InvalidItems;
        }
        for (self.equipment_goods, 0..) |item, i| {
            if (item.uses != 0 or item.id.maxUses() != 0 or !std.mem.eql(u8, item.name, item.id.name())) return error.InvalidItems;
            for (self.equipment_goods[0..i]) |other| if (other.id == item.id) return error.InvalidItems;
        }
        if (self.medicine.price == 0 or self.medicine.uses != 6 or self.medicine.heal_hp == 0) return error.InvalidItems;
        if (self.consumables.len > 4 or (!legacy and self.consumables.len != 4) or self.stock.len == 0 or self.stock.len > 4) return error.InvalidItems;
        for (self.consumables, 0..) |item, i| {
            if (!item.field_usable) return error.InvalidItems;
            if (item.battle) |effect| if (effect.targeting != .single or !effect.reset_pose) return error.InvalidItems;
            if (battle_items and item.battle == null) return error.InvalidItems;
            if (item.battle) |effect| {
                if (effect.pending_delay == 0 or effect.pending_delay > effect.impact_delay or effect.impact_delay >= effect.release_delay or effect.release_delay > 256 or effect.particles.len > 128) return error.InvalidItems;
                for (effect.particles) |row| {
                    if (row.len > 8) return error.InvalidItems;
                    for (row) |position| for (position) |v| if (!std.math.isFinite(v) or @abs(v) > 1024) return error.InvalidItems;
                }
            }
            if (item.uses == 0 or item.uses != item.id.maxUses() or item.price == 0 or !std.mem.eql(u8, item.name, item.id.name()) or (item.heal_hp > 0) == (item.cure != null)) return error.InvalidItems;
            for (self.consumables[0..i]) |previous| if (previous.id == item.id) return error.InvalidItems;
        }
        if (self.battle_reusables.len != @as(usize, if (reusables) 1 else 0)) return error.InvalidItems;
        for (self.battle_reusables) |item| {
            if (item.id != .dragon_seal_incense or item.price != 0 or item.uses != 0 or item.heal_hp != 50 or item.cure != null or item.field_usable or !std.mem.eql(u8, item.name, item.id.name())) return error.InvalidItems;
            const effect = item.battle orelse return error.InvalidItems;
            if (effect.targeting != .party or effect.reset_pose or effect.pending_delay != 31 or effect.impact_delay != 32 or effect.release_delay != 65 or effect.particles.len != 29) return error.InvalidItems;
            for (effect.particles) |row| {
                if (row.len != 2) return error.InvalidItems;
                for (row) |position| for (position) |v| if (!std.math.isFinite(v) or @abs(v) > 1024) return error.InvalidItems;
            }
        }
        const med = self.consumable(.medicine) orelse return error.InvalidItems;
        if (med.price != self.medicine.price or med.uses != self.medicine.uses or med.heal_hp != self.medicine.heal_hp or !std.mem.eql(u8, med.name, self.medicine.name)) return error.InvalidItems;
        for (self.stock, 0..) |id, i| {
            const item = self.good(id) orelse return error.InvalidItems;
            if (item.price == 0) return error.InvalidItems;
            for (self.stock[0..i]) |previous| if (previous == id) return error.InvalidItems;
        }
        for ([_][]const u8{ self.room, self.npc, self.greeting, self.medicine.name }) |value| {
            if (value.len == 0 or value.len > 256 or !std.unicode.utf8ValidateSlice(value)) return error.InvalidItems;
            for (value) |c| if (c < 32 or c == 127) return error.InvalidItems;
        }
    }
};

pub fn load(allocator: std.mem.Allocator, bytes: []const u8) !std.json.Parsed(Rules) {
    if (bytes.len > 256 * 1024) return error.ItemDataTooLarge;
    const parsed = try std.json.parseFromSlice(Rules, allocator, bytes, .{ .allocate = .alloc_always });
    errdefer parsed.deinit();
    try parsed.value.validate();
    return parsed;
}
